settings.custom_liquid:
{%- assign img = collection.image -%}
{%- assign heading = collection.title -%}

{%- if img != blank -%}
<div id="cbpx" class="cbpx" data-cbp-factor="0.25">
  <img class="cbpx__img"
       src="{{ img | image_url: width: 2000 }}"
       srcset="{{ img | image_url: width: 800 }} 800w, {{ img | image_url: width: 1400 }} 1400w, {{ img | image_url: width: 2000 }} 2000w"
       sizes="100vw" alt="{{ heading | escape }}" loading="eager">
  <div class="cbpx__overlay"></div>
  <div class="cbpx__content"><h1 class="cbpx__title">{{ heading }}</h1></div>
</div>

<style>
  #cbpx { position: relative; width: 100%; overflow: hidden; height: 320px; background: #0B1120; display: block; }
  #cbpx .cbpx__img { position: absolute; left: 0; top: -40%; width: 100%; height: 180%; object-fit: cover; object-position: center; will-change: transform; transform: translate3d(0,0,0); backface-visibility: hidden; }
  #cbpx .cbpx__overlay { position: absolute; inset: 0; z-index: 1; background: #0B1120; opacity: .35; }
  #cbpx .cbpx__content { position: relative; z-index: 2; height: 100%; display: flex; align-items: center; justify-content: center; text-align: center; padding: 0 20px; box-sizing: border-box; }
  #cbpx .cbpx__title { margin: 0; color: #fff; font-size: 36px; line-height: 1.04; text-transform: uppercase; letter-spacing: .02em; text-shadow: 0 2px 20px rgba(0,0,0,.35); }
  @media (min-width: 750px) { #cbpx { height: 480px; } #cbpx .cbpx__title { font-size: 64px; } }
</style>

<script>
(function () {
  var el = document.getElementById('cbpx'); if (!el) return;
  var img = el.querySelector('.cbpx__img'); if (!img) return;
  var node = el.parentElement;
  while (node) {
    node.style.paddingTop = '0'; node.style.paddingBottom = '0';
    node.style.marginTop = '0'; node.style.marginBottom = '0';
    if (node.classList && node.classList.contains('shopify-section')) break;
    node = node.parentElement;
  }
  var factor = parseFloat(el.getAttribute('data-cbp-factor')) || 0.25;
  var ticking = false;
  function update() {
    ticking = false;
    var r = el.getBoundingClientRect();
    var vh = window.innerHeight || document.documentElement.clientHeight;
    if (r.bottom < -50 || r.top > vh + 50) return;
    var shift = -r.top * factor;
    var max = r.height * 0.40;
    if (shift > max) shift = max; else if (shift < -max) shift = -max;
    img.style.transform = 'translate3d(0,' + shift.toFixed(2) + 'px,0)';
  }
  function onScroll() { if (!ticking) { ticking = true; window.requestAnimationFrame(update); } }
  window.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onScroll, { passive: true });
  update();
})();
</script>
{%- endif -%}
